y = np.array([lab2i[p['label']] for p in P])[:1024]
rng = np.random.default_rng(0); perm = rng.permutation(1024); folds = np.array_split(perm, 5)
def ridge_cv(X, y, lams, std=True):
    res = {}
    n,d = X.shape
    for lam in lams:
        correct = 0
        for f in folds:
            tr = np.setdiff1d(np.arange(n), f)
            mu = X[tr].mean(0); sd = X[tr].std(0)+1e-6 if std else 1
            Xt = (X[tr]-mu)/sd; Xv = (X[f]-mu)/sd
            Y = np.eye(8)[y[tr]]
            Wt = np.linalg.solve(Xt.T@Xt + lam*np.eye(d), Xt.T@(Y-Y.mean(0)))
            correct += ((Xv@Wt).argmax(1)==y[f]).sum()
        res[lam] = round(correct/n,3)
    return res
